1247	    public void doDecSetOrReset(boolean setting, int externalBit) {
1248	        int internalBit = mapDecSetBitToInternalBit(externalBit);
1249	        if (internalBit != -1) {
1250	            setDecsetinternalBit(internalBit, setting);
1251	        }
1252	        switch (externalBit) {
1253	            case 1: // Application Cursor Keys (DECCKM).
1254	                break;
1255	            case 3: // Set: 132 column mode (. Reset: 80 column mode. ANSI name: DECCOLM.
1256	                // We don't actually set/reset 132 cols, but we do want the side effects
1257	                // (FIXME: Should only do this if the 95 DECSET bit (DECNCSM) is set, and if changing value?):
1258	                // Sets the left, right, top and bottom scrolling margins to their default positions, which is important for
1259	                // the "reset" utility to really reset the terminal:
1260	                mLeftMargin = mTopMargin = 0;
1261	                mBottomMargin = mRows;
1262	                mRightMargin = mColumns;
1263	                // "DECCOLM resets vertical split screen mode (DECLRMM) to unavailable":
1264	                setDecsetinternalBit(DECSET_BIT_LEFTRIGHT_MARGIN_MODE, false);
1265	                // "Erases all data in page memory":
1266	                blockClear(0, 0, mColumns, mRows);
1267	                setCursorRowCol(0, 0);
1268	                break;
1269	            case 4: // DECSCLM-Scrolling Mode. Ignore.
1270	                break;
1271	            case 5: // Reverse video. No action.
1272	                break;
1273	            case 6: // Set: Origin Mode. Reset: Normal Cursor Mode. Ansi name: DECOM.
1274	                if (setting) setCursorPosition(0, 0);
1275	                break;
1276	            case 7: // Wrap-around bit, not specific action.
1277	            case 8: // Auto-repeat Keys (DECARM). Do not implement.
1278	            case 9: // X10 mouse reporting - outdated. Do not implement.
1279	            case 12: // Control cursor blinking - ignore.
1280	            case 25: // Hide/show cursor - no action needed, renderer will check with shouldCursorBeVisible().
1281	                if (mClient != null)
1282	                    mClient.onTerminalCursorStateChange(setting);
1283	                break;
1284	            case 40: // Allow 80 => 132 Mode, ignore.
1285	            case 45: // TODO: Reverse wrap-around. Implement???
1286	            case 66: // Application keypad (DECNKM).
1287	                break;
1288	            case 69: // Left and right margin mode (DECLRMM).
1289	                if (!setting) {
1290	                    mLeftMargin = 0;
1291	                    mRightMargin = mColumns;
1292	                }
1293	                break;
1294	            case 1000:
1295	            case 1001:
1296	            case 1002:
1297	            case 1003:
1298	            case 1004:
1299	            case 1005: // UTF-8 mouse mode, ignore.
1300	            case 1006: // SGR Mouse Mode
1301	            case 1015:
1302	            case 1034: // Interpret "meta" key, sets eighth bit.
1303	                break;
1304	            case 1048: // Set: Save cursor as in DECSC. Reset: Restore cursor as in DECRC.
1305	                if (setting)
1306	                    saveCursor();
1307	                else
1308	                    restoreCursor();
1309	                break;
1310	            case 47:
1311	            case 1047:
1312	            case 1049:
1313	                doDecSetSwitchAltScreen(setting);
1314	                break;
1315	            case 2004:
1316	                // Bracketed paste mode - setting bit is enough.
1317	                break;
1318	            default:
1319	                unknownParameter(externalBit);
